package org.skilltro;

import jakarta.servlet.http.HttpSession;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import java.util.*;
import java.util.stream.*;
import static org.skilltro.Domain.*;

@RestController @RequestMapping("/api")
class Api {
  private final UserRepo users; private final WorkerRepo workers; private final EmployerRepo employers;
  private final SkillRepo skills; private final WorkerSkillRepo workerSkills; private final QuestionRepo questions;
  private final AttemptRepo attempts; private final JobRepo jobs; private final JobSkillRepo jobSkills; private final ApplicationRepo applications;
  private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();
  Api(UserRepo u,WorkerRepo w,EmployerRepo e,SkillRepo s,WorkerSkillRepo ws,QuestionRepo q,AttemptRepo a,JobRepo j,JobSkillRepo js,ApplicationRepo ap){users=u;workers=w;employers=e;skills=s;workerSkills=ws;questions=q;attempts=a;jobs=j;jobSkills=js;applications=ap;}
  record Register(@Email @NotBlank String email,@NotBlank @Size(min=8) String password,@NotBlank String name,@NotNull Role role){}
  record Login(@Email @NotBlank String email,@NotBlank String password){}
  record Profile(String occupation,int experienceYears,String location,String workDescription,String organization,String description){}
  record SkillInput(Long id,String name,String state,String evidence){}
  record JobInput(@NotBlank String title,@NotBlank String location,String description,List<String> required,List<String> preferred,String safetyRequirements){}
  record Answer(Long questionId,int option){}
  record ApplyStatus(String status){}
  private User current(HttpSession s){Object id=s.getAttribute("uid");if(id==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Please sign in");return users.findById((Long)id).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
  private User requireRole(HttpSession s,Role r){User u=current(s);if(u.role!=r)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This action is not available for your account");return u;}
  private WorkerProfile worker(HttpSession s){return workers.findByUserId(requireRole(s,Role.WORKER).id).orElseThrow();}
  private EmployerProfile employer(HttpSession s){return employers.findByUserId(requireRole(s,Role.EMPLOYER).id).orElseThrow();}
  private Skill skill(String name){return skills.findByNameIgnoreCase(name.trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown skill: "+name));}
  @PostMapping("/auth/register") @ResponseStatus(HttpStatus.CREATED) Map<String,Object> register(@Valid @RequestBody Register in,HttpSession session,HttpServletRequest request){
    if(users.findByEmailIgnoreCase(in.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");
    User u=new User();u.email=in.email().toLowerCase();u.passwordHash=encoder.encode(in.password());u.name=in.name();u.role=in.role();users.save(u);
    if(u.role==Role.WORKER){WorkerProfile p=new WorkerProfile();p.user=u;p.location="";p.occupation="";p.workDescription="";workers.save(p);}else{EmployerProfile p=new EmployerProfile();p.user=u;p.organization=in.name();p.location="";p.description="";employers.save(p);}
    request.changeSessionId();session.setAttribute("uid",u.id);return Map.of("id",u.id,"email",u.email,"name",u.name,"role",u.role);
  }
  @PostMapping("/auth/login") Map<String,Object> login(@Valid @RequestBody Login in,HttpSession session,HttpServletRequest request){User u=users.findByEmailIgnoreCase(in.email()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect"));if(!encoder.matches(in.password(),u.passwordHash))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect");request.changeSessionId();session.setAttribute("uid",u.id);return Map.of("id",u.id,"email",u.email,"name",u.name,"role",u.role);}
  @PostMapping("/auth/logout") Map<String,String> logout(HttpSession s){s.invalidate();return Map.of("message","Signed out");}
  @GetMapping("/auth/me") Map<String,Object> me(HttpSession s){User u=current(s);return Map.of("id",u.id,"email",u.email,"name",u.name,"role",u.role);}
  @GetMapping("/skills") List<Map<String,Object>> allSkills(){return skills.findAll().stream().map(x->Map.<String,Object>of("id",x.id,"name",x.name,"category",x.category==null?"":x.category)).toList();}
  @GetMapping("/worker/profile") Map<String,Object> workerProfile(HttpSession s){WorkerProfile p=worker(s);return Map.of("id",p.id,"name",p.user.name,"occupation",safe(p.occupation),"experienceYears",p.experienceYears,"location",safe(p.location),"workDescription",safe(p.workDescription),"skills",workerSkills.findByWorkerProfileIdAndState(p.id,"CONFIRMED").stream().map(x->x.skill.name).toList());}
  @PutMapping("/worker/profile") Map<String,Object> saveWorkerProfile(@RequestBody Profile in,HttpSession s){WorkerProfile p=worker(s);p.occupation=in.occupation();p.experienceYears=Math.max(0,in.experienceYears());p.location=in.location();p.workDescription=in.workDescription();workers.save(p);return workerProfile(s);}
  private String safe(String s){return s==null?"":s;}
  @GetMapping("/worker/suggestions") List<Map<String,Object>> suggestions(HttpSession s){WorkerProfile p=worker(s);String text=safe(p.occupation)+" "+safe(p.workDescription);Set<String> reviewed=workerSkills.findByWorkerProfileId(p.id).stream().map(x->x.skill.name).collect(Collectors.toSet());return SkillSuggestionRules.suggest(skills.findAll().stream().map(sk->sk.name).toList(),text,reviewed).stream().map(name->{Skill sk=skill(name);return Map.<String,Object>of("id",sk.id,"name",sk.name);}).toList();}
  @PostMapping("/worker/skills") Map<String,Object> updateSkill(@RequestBody SkillInput in,HttpSession s){WorkerProfile p=worker(s);if(in.id()==null&&(in.name()==null||in.name().isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Skill id or name is required");if(in.state()!=null&&!Set.of("CONFIRMED","REJECTED").contains(in.state().toUpperCase()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"State must be CONFIRMED or REJECTED");Skill sk=in.id()!=null?skills.findById(in.id()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown skill id")):skill(in.name());String state="REJECTED".equalsIgnoreCase(in.state())?"REJECTED":"CONFIRMED";WorkerSkill ws=workerSkills.findByWorkerProfileId(p.id).stream().filter(x->x.skill.id.equals(sk.id)).findFirst().orElseGet(WorkerSkill::new);ws.workerProfile=p;ws.skill=sk;ws.state=state;ws.evidence=state.equals("CONFIRMED")?"Worker confirmed":"Worker rejected suggestion";workerSkills.save(ws);return Map.of("message",state.equals("CONFIRMED")?"Skill confirmed":"Suggestion rejected","skill",sk.name,"state",state);}
  @GetMapping("/worker/assessments") List<Map<String,Object>> assessmentList(HttpSession s){worker(s);return skills.findAll().stream().map(sk->Map.<String,Object>of("skill",sk.name,"skillId",sk.id,"questions",questions.findBySkillId(sk.id).size())).filter(x->(int)x.get("questions")>0).toList();}
  @GetMapping("/worker/assessments/{skillId}") List<Map<String,Object>> assessment(@PathVariable Long skillId,HttpSession s){worker(s);return questions.findBySkillId(skillId).stream().map(q->Map.<String,Object>of("id",q.id,"prompt",q.prompt,"options",List.of(q.optionA,q.optionB,q.optionC,q.optionD))).toList();}
  @PostMapping("/worker/assessments/{skillId}/submit") Map<String,Object> submitAssessment(@PathVariable Long skillId,@RequestBody List<Answer> answers,HttpSession s){WorkerProfile p=worker(s);Skill sk=skills.findById(skillId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Assessment skill not found"));List<Question> qs=questions.findBySkillId(skillId);if(qs.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"No assessment is available for this skill");if(answers==null||answers.size()!=qs.size())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Submit exactly one answer for each question");Set<Long> validQuestionIds=qs.stream().map(q->q.id).collect(Collectors.toSet());Set<Long> seen=new HashSet<>();for(Answer answer:answers){if(answer.questionId()==null||!validQuestionIds.contains(answer.questionId())||!seen.add(answer.questionId())||answer.option()<0||answer.option()>3)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Each question needs one valid option");}int score=(int)answers.stream().filter(a->qs.stream().anyMatch(q->q.id.equals(a.questionId())&&q.correctOption==a.option())).count();Attempt at=new Attempt();at.workerProfile=p;at.skill=sk;at.score=score;at.total=qs.size();at.answersJson=answers.toString();attempts.save(at);return Map.of("score",score,"total",qs.size(),"notice","Quiz results indicate knowledge only; they do not prove practical competence.");}
  @GetMapping("/worker/assessments/results") List<Map<String,Object>> results(HttpSession s){WorkerProfile p=worker(s);return attempts.findByWorkerProfileIdOrderByCreatedAtDesc(p.id).stream().map(a->Map.<String,Object>of("skill",a.skill.name,"score",a.score,"total",a.total,"createdAt",a.createdAt,"notice","Knowledge check only; not proof of practical competence.")).toList();}
  private Map<String,Object> match(Job j,WorkerProfile w){Set<Long> confirmed=workerSkills.findByWorkerProfileIdAndState(w.id,"CONFIRMED").stream().map(x->x.skill.id).collect(Collectors.toSet());List<JobSkill> req=jobSkills.findByJobId(j.id);List<JobSkill> required=req.stream().filter(x->x.requirementType.equals("REQUIRED")).toList();List<JobSkill> preferred=req.stream().filter(x->x.requirementType.equals("PREFERRED")).toList();List<String> hit=required.stream().filter(x->confirmed.contains(x.skill.id)).map(x->x.skill.name).toList();List<String> missing=required.stream().filter(x->!confirmed.contains(x.skill.id)).map(x->x.skill.name).toList();int pct=MatchingRules.requiredSkillOverlap(hit.size(),required.size());Map<String,Object> result=new LinkedHashMap<>();result.put("jobId",j.id);result.put("title",j.title);result.put("location",j.location);result.put("description",safe(j.description));result.put("demo",j.demo);result.put("open",j.open);result.put("employer",j.employer.organization);result.put("matchedSkills",hit);result.put("missingSkills",missing);result.put("preferredSkills",preferred.stream().map(x->x.skill.name).toList());result.put("matchPercentage",pct);result.put("safetyRequirements",safe(j.safetyRequirements));result.put("mandatoryRequirementsMet",missing.isEmpty());return result;}
  @GetMapping("/worker/jobs") List<Map<String,Object>> discoverJobs(HttpSession s){WorkerProfile w=worker(s);return jobs.findByOpenTrueOrderByCreatedAtDesc().stream().map(j->match(j,w)).toList();}
  @PostMapping("/worker/jobs/{id}/apply") Map<String,Object> apply(@PathVariable Long id,HttpSession s){WorkerProfile w=worker(s);Job j=jobs.findById(id).orElseThrow();if(!j.open)throw new ResponseStatusException(HttpStatus.CONFLICT,"This opportunity is closed");if(applications.existsByJobIdAndWorkerProfileId(id,w.id))throw new ResponseStatusException(HttpStatus.CONFLICT,"You have already applied");Application a=new Application();a.job=j;a.workerProfile=w;a.status="SUBMITTED";applications.save(a);return Map.of("message","Application submitted","id",a.id);}
  @GetMapping("/worker/applications") List<Map<String,Object>> myApplications(HttpSession s){WorkerProfile w=worker(s);return applications.findByWorkerProfileId(w.id).stream().map(a->Map.<String,Object>of("id",a.id,"jobId",a.job.id,"title",a.job.title,"employer",a.job.employer.organization,"status",a.status,"createdAt",a.createdAt)).toList();}
  @GetMapping("/employer/profile") Map<String,Object> employerProfile(HttpSession s){EmployerProfile p=employer(s);return Map.of("id",p.id,"name",p.user.name,"organization",safe(p.organization),"location",safe(p.location),"description",safe(p.description));}
  @PutMapping("/employer/profile") Map<String,Object> saveEmployerProfile(@RequestBody Profile in,HttpSession s){EmployerProfile p=employer(s);p.organization=in.organization();p.location=in.location();p.description=in.description();employers.save(p);return employerProfile(s);}
  private Job createOrUpdateJob(Job j,JobInput in,EmployerProfile e){if(in.title()==null||in.title().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Job title is required");if(in.location()==null||in.location().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Job location is required");List<Skill> required=resolveJobSkills(Optional.ofNullable(in.required()).orElse(List.of()));List<Skill> preferred=resolveJobSkills(Optional.ofNullable(in.preferred()).orElse(List.of()));Set<String> requiredNames=required.stream().map(x->x.name.toLowerCase()).collect(Collectors.toSet());if(requiredNames.size()!=required.size())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Required skills must not contain duplicates");Set<String> preferredNames=preferred.stream().map(x->x.name.toLowerCase()).collect(Collectors.toSet());if(preferredNames.size()!=preferred.size())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Preferred skills must not contain duplicates");if(preferredNames.stream().anyMatch(requiredNames::contains))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A skill cannot be both required and preferred");boolean creating=j.id==null;j.employer=e;j.title=in.title();j.location=in.location();j.description=in.description();j.safetyRequirements=safe(in.safetyRequirements());j.demo=true;if(creating)j.open=true;jobs.save(j);jobSkills.deleteAll(jobSkills.findByJobId(j.id));for(Skill sk:required){JobSkill x=new JobSkill();x.job=j;x.skill=sk;x.requirementType="REQUIRED";jobSkills.save(x);}for(Skill sk:preferred){JobSkill x=new JobSkill();x.job=j;x.skill=sk;x.requirementType="PREFERRED";jobSkills.save(x);}return j;}
  private List<Skill> resolveJobSkills(List<String> names){return names.stream().map(name->{if(name==null||name.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Skill names must not be empty");return skill(name);}).toList();}
  @GetMapping("/employer/jobs") List<Map<String,Object>> employerJobs(HttpSession s){EmployerProfile e=employer(s);return jobs.findByEmployerId(e.id).stream().map(j->{Map<String,Object> m=new LinkedHashMap<>(match(j,emptyWorker()));m.put("requiredSkills",jobSkills.findByJobId(j.id).stream().filter(x->x.requirementType.equals("REQUIRED")).map(x->x.skill.name).toList());return m;}).toList();}
  private WorkerProfile emptyWorker(){WorkerProfile w=new WorkerProfile();w.id=-1L;return w;}
  @PostMapping("/employer/jobs") @ResponseStatus(HttpStatus.CREATED) Map<String,Object> createJob(@Valid @RequestBody JobInput in,HttpSession s){Job j=createOrUpdateJob(new Job(),in,employer(s));return Map.of("id",j.id,"message","Demo opportunity created");}
  @PutMapping("/employer/jobs/{id}") Map<String,Object> editJob(@PathVariable Long id,@Valid @RequestBody JobInput in,HttpSession s){EmployerProfile e=employer(s);Job j=jobs.findById(id).filter(x->x.employer.id.equals(e.id)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));createOrUpdateJob(j,in,e);return Map.of("message","Opportunity updated");}
  @PostMapping("/employer/jobs/{id}/close") Map<String,Object> closeJob(@PathVariable Long id,HttpSession s){EmployerProfile e=employer(s);Job j=jobs.findById(id).filter(x->x.employer.id.equals(e.id)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));j.open=false;jobs.save(j);return Map.of("message","Opportunity closed");}
  @GetMapping("/employer/workers") List<Map<String,Object>> discoverWorkers(@RequestParam(required=false) String skill,@RequestParam(required=false) String location,HttpSession s){employer(s);return workers.findAll().stream().filter(w->location==null||safe(w.location).toLowerCase().contains(location.toLowerCase())).filter(w->skill==null||workerSkills.findByWorkerProfileIdAndState(w.id,"CONFIRMED").stream().anyMatch(x->x.skill.name.equalsIgnoreCase(skill))).map(w->workerCard(w,skill)).toList();}
  private Map<String,Object> workerCard(WorkerProfile w,String search){List<String> confirmed=workerSkills.findByWorkerProfileIdAndState(w.id,"CONFIRMED").stream().map(x->x.skill.name).toList();List<String> results=attempts.findByWorkerProfileIdOrderByCreatedAtDesc(w.id).stream().map(a->a.skill.name+" "+a.score+"/"+a.total+" (knowledge check)").toList();return Map.of("id",w.id,"name",w.user.name,"occupation",safe(w.occupation),"experienceYears",w.experienceYears,"location",safe(w.location),"workDescription",safe(w.workDescription),"confirmedSkills",confirmed,"assessmentResults",results,"matchingSkills",search==null?List.of():confirmed.stream().filter(x->x.equalsIgnoreCase(search)).toList());}
  @GetMapping("/employer/applications") List<Map<String,Object>> employerApplications(HttpSession s){EmployerProfile e=employer(s);return applications.findByJobEmployerId(e.id).stream().map(a->{Map<String,Object> m=new LinkedHashMap<>(workerCard(a.workerProfile,null));m.put("applicationId",a.id);m.put("jobId",a.job.id);m.put("jobTitle",a.job.title);m.put("status",a.status);m.put("missingSkills",((List<String>)match(a.job,a.workerProfile).get("missingSkills")));m.put("matchPercentage",match(a.job,a.workerProfile).get("matchPercentage"));return m;}).toList();}
  @PutMapping("/employer/applications/{id}") Map<String,Object> updateApplication(@PathVariable Long id,@RequestBody ApplyStatus in,HttpSession s){EmployerProfile e=employer(s);Application a=applications.findById(id).filter(x->x.job.employer.id.equals(e.id)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!Set.of("REVIEWING","SHORTLISTED","REJECTED","ACCEPTED").contains(in.status()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Status must be REVIEWING, SHORTLISTED, REJECTED, or ACCEPTED");a.status=in.status();applications.save(a);return Map.of("id",a.id,"status",a.status);}
}

@Configuration class SeedData {
  @Bean CommandLineRunner seed(UserRepo users,WorkerRepo workers,EmployerRepo employers,SkillRepo skills,QuestionRepo questions,JobRepo jobs,JobSkillRepo jobSkills){return args->{
    String[] names={"Carpentry","Welding","Electrical wiring","Plumbing","Masonry","Painting","Cooking","Driving","Machine operation","First aid"};for(String n:names)if(skills.findByNameIgnoreCase(n).isEmpty()){Skill s=new Skill();s.name=n;s.category="Practical";skills.save(s);}
    if(questions.count()==0){String[][] qa={{"Before replacing a wall switch, what is the first safety step?","Turn off circuit and verify power is off","Use an insulated screwdriver only","Ask someone to watch","Work quickly"},{"What helps prevent a welded joint from cracking?","Correct heat and clean base metal","More paint","Cool with water every time","Skip surface prep"},{"What should you do before loosening a water supply fitting?","Shut off and relieve pressure","Add sealant outside","Heat the pipe","Open another tap only"}};String[] sk={"Electrical wiring","Welding","Plumbing"};for(int i=0;i<qa.length;i++){Question q=new Question();q.skill=skills.findByNameIgnoreCase(sk[i]).orElseThrow();q.prompt=qa[i][0];q.optionA=qa[i][1];q.optionB=qa[i][2];q.optionC=qa[i][3];q.optionD=qa[i][4];q.correctOption=0;questions.save(q);}}
    if(users.count()==0){User u=new User();u.email="worker.demo@skilltro.local";u.name="Demo Worker";u.passwordHash=new BCryptPasswordEncoder().encode("worker-demo-123");u.role=Role.WORKER;users.save(u);WorkerProfile w=new WorkerProfile();w.user=u;w.occupation="Carpenter";w.experienceYears=5;w.location="Pune";w.workDescription="I build furniture, do woodwork and repair doors.";workers.save(w);User e=new User();e.email="employer.demo@skilltro.local";e.name="Demo Employer";e.passwordHash=new BCryptPasswordEncoder().encode("employer-demo-123");e.role=Role.EMPLOYER;users.save(e);EmployerProfile ep=new EmployerProfile();ep.user=e;ep.organization="SkillTro Demo Works";ep.location="Pune";ep.description="Sample employer for demo opportunities.";employers.save(ep);String[][] js={{"Workshop Carpenter","Pune","Build and repair furniture with a small workshop team.","Carpentry","Painting"},{"Site Electrical Helper","Pune","Assist a licensed electrician with safe wiring installation.","Electrical wiring","First aid"},{"Community Kitchen Cook","Mumbai","Prepare meals for a neighborhood kitchen.","Cooking","Driving"}};for(String[] row:js){Job j=new Job();j.employer=ep;j.title=row[0];j.location=row[1];j.description=row[2];j.demo=true;j.safetyRequirements=row[0].contains("Electrical")?"Licensed electrician supervision required; this listing does not replace legal licensing.":"";jobs.save(j);for(int i=3;i<row.length;i++){JobSkill x=new JobSkill();x.job=j;x.skill=skills.findByNameIgnoreCase(row[i]).orElseThrow();x.requirementType=i==3?"REQUIRED":"PREFERRED";jobSkills.save(x);}}}
  };}
}
